T.permissions=function(root){
 var sys=[['Accounting software','Owner only',true,false],['Customer database','Everyone',false,true],['Company email','Managers',true,false],['Website admin','Everyone',false,true],['Wi-Fi router','Managers',false,true]];
 root.innerHTML='<div class="panel"><p class="muted">Change each system the way it is set up today. See the issues a review would flag, and whether it is safe to connect an AI tool.</p><div class="table-wrap"><table><thead><tr><th>System</th><th>Who has access</th><th>Two-step sign-in</th><th>Shared password</th><th>Review result</th></tr></thead><tbody>'+sys.map(function(s,i){return '<tr><td>'+esc(s[0])+'</td><td><select data-w="'+i+'" style="min-width:130px" aria-label="Who has access to '+esc(s[0])+'"><option'+(s[1]==='Everyone'?' selected':'')+'>Everyone</option><option'+(s[1]==='Managers'?' selected':'')+'>Managers</option><option'+(s[1]==='Owner only'?' selected':'')+'>Owner only</option></select></td><td><input type="checkbox" data-m="'+i+'"'+(s[2]?' checked':'')+' aria-label="Two-step sign-in for '+esc(s[0])+'"></td><td><input type="checkbox" data-p="'+i+'"'+(s[3]?' checked':'')+' aria-label="Shared password for '+esc(s[0])+'"></td><td id="r'+i+'"></td></tr>'}).join('')+'</tbody></table></div></div><div class="metrics three" style="margin-top:14px"><div class="metric"><label>High priority</label><strong id="p1">0</strong></div><div class="metric"><label>Medium</label><strong id="p2">0</strong></div><div class="metric"><label>Ready for an AI tool</label><strong id="p3">0</strong><small>of 5 systems</small></div></div>';
 function calc(){var h=0,m=0,ok=0;sys.forEach(function(s,i){var who=q('[data-w="'+i+'"]',root).value,mfa=q('[data-m="'+i+'"]',root).checked,pw=q('[data-p="'+i+'"]',root).checked,issues=[],sev=0;
  if(pw){issues.push('shared password');sev=2}if(who==='Everyone'&&i!==2&&i!==4){issues.push('everyone has access');sev=Math.max(sev,2)}if(!mfa){issues.push('no two-step sign-in');sev=Math.max(sev,1)}
  var c=q('#r'+i,root);if(sev===2){h++;c.innerHTML=tag('High: '+issues.join(', '),'solid')}else if(sev===1){m++;c.innerHTML=tag('Medium: '+issues.join(', '),'outline')}else{ok++;c.innerHTML=tag('Ready','mute')}});
  q('#p1',root).textContent=h;q('#p2',root).textContent=m;q('#p3',root).textContent=ok}
 on(root,'select','change',calc);on(root,'input','change',calc);calc();
};

